<script lang="ts">
 import type{DesignSnapshot,DesignElement}from'@schubert/contracts';
 type Boundary=Extract<DesignElement,{kind:'room'}>['boundary'];
 let{snapshot,boundary=$bindable(),disabled=false}:{snapshot:DesignSnapshot;boundary:Boundary;disabled?:boolean}=$props();
 const walls=$derived(snapshot.elements.filter(e=>e.kind==='wall'&&e.phase!=='demolition'));
 function ends(row:Boundary[number]){const wall=walls.find(w=>w.id===row.wallId);return wall?.kind==='wall'?row.side==='left'?[wall.startNodeId,wall.endNodeId]:[wall.endNodeId,wall.startNodeId]:null;}
 const closed=$derived(boundary.length>=3&&new Set(boundary.map(b=>b.wallId)).size===boundary.length&&boundary.every((b,i)=>{const a=ends(b),next=ends(boundary[(i+1)%boundary.length]);return a&&next&&a[1]===next[0];}));
 function order(index:number,delta:number){const next=boundary.map(b=>({...b})),to=index+delta;if(to<0||to>=next.length)return;[next[index],next[to]]=[next[to],next[index]];boundary=next;}
</script>
<div class="boundary-fields"><p>Wände in umlaufender Reihenfolge auswählen. Links folgt dem Anfangs- zum Endknoten, rechts kehrt die Richtung für diese Raumgrenze um. Eine gemeinsame Wand kann zwei Räume auf ihren gegenüberliegenden Seiten begrenzen.</p>
 {#each boundary as row,index}<div class="boundary-row"><strong>Abschnitt {index+1}</strong><label>Wand<select bind:value={row.wallId} {disabled}><option value="">Vorhandene Wand wählen</option>{#each walls as wall}<option value={wall.id}>{wall.label}</option>{/each}</select></label><label>Raumseite<select bind:value={row.side} {disabled}><option value="left">Links · Anfang → Ende</option><option value="right">Rechts · Ende → Anfang</option></select></label><div class="actions"><button type="button" onclick={()=>order(index,-1)} disabled={disabled||index===0} aria-label={`Grenzabschnitt ${index+1} nach vorne`}>Nach vorne</button><button type="button" onclick={()=>order(index,1)} disabled={disabled||index===boundary.length-1} aria-label={`Grenzabschnitt ${index+1} nach hinten`}>Nach hinten</button><button type="button" onclick={()=>boundary=boundary.filter((_,i)=>i!==index)} {disabled}>Abschnitt entfernen</button></div></div>{/each}
 <button type="button" class="btn small" onclick={()=>boundary=[...boundary,{wallId:'',side:'left'}]} {disabled}>Wandgrenze ergänzen</button><p class:valid={closed} class="boundary-status" role="status">{closed?'Knotenfolge geschlossen. Die geometrische Prüfung erfolgt bei der Übernahme.':'Noch kein geschlossener Wandumlauf. Mindestens drei unterschiedliche Wände mit exakt gemeinsamen Anschlussknoten auswählen.'}</p>
</div>
<style>.boundary-fields{font-size:13px;line-height:1.65}.boundary-fields p{font-size:12px;color:var(--muted)}.boundary-row{border:1px solid var(--line);padding:12px;margin:12px 0;background:var(--paper)}.boundary-row strong{font-size:13px}.boundary-row label{display:block;font-size:13px;margin-top:12px}.boundary-row select{display:block;box-sizing:border-box;width:100%;font:inherit;font-size:14px;color:var(--ink);background:var(--paper);border:1px solid var(--line);border-radius:4px;padding:10px;margin-top:5px;min-height:44px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.actions button{font:inherit;font-size:12px;min-height:36px;border:0;background:none;color:var(--forest);cursor:pointer;padding:4px}.actions button:disabled{opacity:.4;cursor:default}.boundary-status{padding:10px;border:1px solid var(--line);background:var(--wash)}.boundary-status.valid{border-color:var(--line);background:var(--wash)}button:focus-visible,select:focus-visible{outline:2px solid var(--forest);outline-offset:2px}@media(max-width:720px){.actions button,.boundary-row select{min-height:48px;font-size:16px}}</style>
